package io.ecosync.chat;
import java.util.*;
import java.time.Duration;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class ChatCoreTest {
 @org.junit.jupiter.api.io.TempDir java.nio.file.Path temp;
 @Test void optionalOllamaCallIdsBecomeFreshHostReferencesWithoutChangingTheProposal(){var call=new org.springframework.ai.chat.messages.AssistantMessage.ToolCall(null,"function","r_approved","{\"limit\":1}");var message=org.springframework.ai.chat.messages.AssistantMessage.builder().content("").toolCalls(List.of(call)).build();var one=OllamaModelPort.proposalIds(message).getToolCalls().getFirst();var two=OllamaModelPort.proposalIds(message).getToolCalls().getFirst();assertThat(one.id()).startsWith("proposal-").isNotEqualTo(two.id());assertThat(one.name()).isEqualTo(call.name());assertThat(one.arguments()).isEqualTo(call.arguments());assertThat(one.type()).isEqualTo(call.type());assertThat(OllamaModelPort.proposalIds(org.springframework.ai.chat.messages.AssistantMessage.builder().content("").toolCalls(List.of(one)).build()).getToolCalls().getFirst().id()).isEqualTo(one.id());}
 @Test void sourceTransportCannotStartAfterItsInheritedDeadline()throws Exception{assertThat(io.ecosync.execution.CallDeadline.limit(Duration.ofSeconds(12))).isEqualTo(Duration.ofSeconds(12));assertThatThrownBy(()->io.ecosync.execution.CallDeadline.within(Duration.ofMillis(5),()->{Thread.sleep(15);io.ecosync.execution.CallDeadline.check();return true;})).isInstanceOf(io.ecosync.execution.CallDeadline.Expired.class);assertThat(io.ecosync.execution.CallDeadline.limit(Duration.ofSeconds(12))).isEqualTo(Duration.ofSeconds(12));}
 @Test void uncitedEvidenceCannotAuthorizeAJoinAndDerivedFactsKeepTheirLineage(){var a=new ChatCapabilities.Capability("n_a","NATIVE",UUID.randomUUID(),UUID.randomUUID(),1,"a","A","read",Map.of(),"sales");var b=new ChatCapabilities.Capability("n_b","NATIVE",UUID.randomUUID(),UUID.randomUUID(),1,"b","B","read",Map.of(),"inventory");var d=new ChatCapabilities.Capability("select_records","DETERMINISTIC",new UUID(0,0),new UUID(0,0),1,"d","Selection","select",Map.of(),"selection");var one=new ChatEvidence("e1",a,UUID.randomUUID(),"SUCCESS",Map.of("id",1001),false);var two=new ChatEvidence("e2",a,UUID.randomUUID(),"SUCCESS",Map.of("id",1002),false);var stock=new ChatEvidence("e3",b,UUID.randomUUID(),"SUCCESS",Map.of("id","WH-700"),false);var selected=new ChatEvidence("e4",d,UUID.randomUUID(),"SUCCESS",Map.of("inputEvidence","e3","records",List.of()),false);var result=EvidenceGrounding.selected(List.of(Map.of("evidence","e2"),Map.of("evidence","e4")),List.of(one,two,stock,selected));assertThat(result.stream().map(ChatEvidence::id)).containsExactly("e2","e3").doesNotContain("e1");}
 @Test void duplicateArgumentsCannotBeCollapsed(){assertThatThrownBy(()->ChatData.object("{\"limit\":1,\"limit\":2}",1024)).isInstanceOf(ChatFailure.class);}
 @Test void budgetIsAcrossTheWholeQueryAndCannotBeIncreased(){var b=new QueryBudget(Duration.ofSeconds(1),8);for(int i=0;i<8;i++)assertThat(b.consume()).isEqualTo(i+1);assertThatThrownBy(b::consume).isInstanceOf(ChatFailure.class).extracting(e->((ChatFailure)e).code).isEqualTo("CHAT_CALL_BUDGET");assertThatThrownBy(()->new QueryBudget(Duration.ofSeconds(31),8)).isInstanceOf(IllegalArgumentException.class);}
 @Test void cancellationImmediatelyFencesFurtherWork(){var b=new QueryBudget(Duration.ofSeconds(1),8);b.cancel();assertThatThrownBy(b::remaining).isInstanceOf(ChatFailure.class).extracting(e->((ChatFailure)e).code).isEqualTo("CHAT_CANCELLED");}
 @Test void deadlineExpiresMonotonically()throws Exception{var b=new QueryBudget(Duration.ofMillis(10),8);Thread.sleep(20);assertThatThrownBy(b::remaining).isInstanceOf(ChatFailure.class).extracting(e->((ChatFailure)e).code).isEqualTo("CHAT_TIMEOUT");}
 @Test void secretFieldsAndSecretLikeValuesNeverReachContext(){Object value=ChatData.clean(Map.of("record",Map.of("password","nope","access_token","nope","name","ordinary","text","Bearer abcdefghijklmnopqrstuvwxyz")));assertThat(ChatData.json(value)).contains("ordinary","[REDACTED]").doesNotContain("nope","abcdefghijklmnopqrstuvwxyz","password");}
 @Test void evidencePointersAreExactAndCannotEvaluateCode(){Object data=Map.of("items",List.of(Map.of("id",42,"cost","12.30")));assertThat(ChatData.pointer(data,"/items/0/cost")).isEqualTo("12.30");for(String p:List.of("/items/-1","/items/99","$..cost","/items/0/missing"))assertThatThrownBy(()->ChatData.pointer(data,p)).isInstanceOf(ChatFailure.class);}
 @Test void excessiveSourceShapeIsRejectedBeforeModelExposure(){assertThatThrownBy(()->ChatData.clean(Map.of("rows",Collections.nCopies(101,Map.of("id",1))))).isInstanceOf(ChatFailure.class);assertThatThrownBy(()->ChatData.clean("x".repeat(4097))).isInstanceOf(ChatFailure.class);}
 @Test void deterministicCalculationUsesActualEvidenceDecimals()throws Exception{UUID org=UUID.randomUUID();var cap=new ChatCapabilities.Capability("r_x","REST",UUID.randomUUID(),UUID.randomUUID(),1,"x","Source","read",Map.of());java.nio.file.Path binding=temp.resolve("bindings.json");java.nio.file.Files.writeString(binding,ChatData.json(Map.of("version","1.0.0","bindings",List.of(Map.of("organization",org.toString(),"kind",cap.kind(),"connector",cap.connector().toString(),"entity",cap.entity().toString(),"revision",1,"fingerprint","x","canonicalSource","fixture","verifiedReadOnly",true,"measures",Map.of("amount",Map.of("currencyField","currency","unitField","unit")))))));var knowledge=new ChatKnowledge(new ChatBindings(new ChatSettings(false,"test","","",3,8,6,65536,16384,binding.toString())));var e=new ChatEvidence("e1",cap,UUID.randomUUID(),"SUCCESS",Map.of("a",Map.of("amount","0.10","currency","EUR","unit","EA"),"b",Map.of("amount","0.20","currency","EUR","unit","EA")),false);var args=Map.<String,Object>of("operation","SUM","currency","EUR","unit","EA","operands",List.of(Map.of("evidence","e1","pointer","/a/amount"),Map.of("evidence","e1","pointer","/b/amount")));assertThat(knowledge.calculate(org,args,List.of(e))).containsEntry("value","0.30");var bad=new HashMap<>(args);bad.put("currency","USD");var incompatible=bad;assertThatThrownBy(()->knowledge.calculate(org,incompatible,List.of(e))).isInstanceOf(ChatFailure.class);bad=new HashMap<>(args);bad.put("value","999");var fabricated=bad;assertThatThrownBy(()->knowledge.calculate(org,fabricated,List.of(e))).isInstanceOf(ChatFailure.class);}
 @Test void eligibilitySelectionKeepsOnlyActualMatchingRecords(){var k=new ChatKnowledge();var cap=new ChatCapabilities.Capability("r_x","REST",UUID.randomUUID(),UUID.randomUUID(),1,"x","Source","read",Map.of());var evidence=new ChatEvidence("e1",cap,UUID.randomUUID(),"SUCCESS",Map.of("items",List.of(Map.of("id","eligible","minimum_order_quantity",5,"available_quantity",20,"currency_code","USD","unit_code","EA"),Map.of("id","too-large-moq","minimum_order_quantity",50,"available_quantity",100,"currency_code","USD","unit_code","EA"))),false);var selected=k.select(Map.of("evidence","e1","pointer","/items","conditions",List.of(Map.of("field","minimum_order_quantity","operator","LTE","value",10),Map.of("field","available_quantity","operator","GTE","value",10),Map.of("field","currency_code","operator","EQ","value","USD"),Map.of("field","unit_code","operator","EQ","value","EA"))),List.of(evidence));assertThat(ChatData.json(selected)).contains("eligible").doesNotContain("too-large-moq");assertThatThrownBy(()->k.select(Map.of("evidence","e1","pointer","/items","conditions",List.of(Map.of("field","missing","operator","EQ","value",1))),List.of(evidence))).isInstanceOf(ChatFailure.class);}
 @Test void mappingCannotUseUnverifiedConnectorNames(){var k=new ChatKnowledge();assertThatThrownBy(()->k.mapping(Map.of("sourceSystem","sales","sourceIdentifier","1001","targetSystem","inventory"),List.of())).isInstanceOf(ChatFailure.class);}
 @Test void seededMappingsRequireUniqueExplicitApproval(){var k=new ChatKnowledge();var a=new ChatCapabilities.Capability("n_a","NATIVE",UUID.randomUUID(),UUID.randomUUID(),1,"a","A","read",Map.of(),"sales");var b=new ChatCapabilities.Capability("n_b","NATIVE",UUID.randomUUID(),UUID.randomUUID(),1,"b","B","read",Map.of(),"inventory");assertThat(k.mapping(Map.of("sourceSystem","sales","sourceIdentifier","1001","targetSystem","inventory"),List.of(a,b))).containsEntry("mappingId","m-sales-1001").containsEntry("mappingVersion","1.0.0");assertThat(k.mapping(Map.of("sourceSystem","sales","sourceIdentifier","no-relationship","targetSystem","inventory"),List.of(a,b))).containsEntry("status","AMBIGUOUS_OR_MISSING");}
}
